head.b:skin:
:root {
  /* GitHub Dark Mode Palette */
  --gh-bg: #0d1117;
  --gh-panel: #161b22;
  --gh-border: #30363d;
  --gh-text: #c9d1d9;
  --gh-muted: #8b949e;
  --gh-link: #58a6ff;

  /* Fluid Hype Gradient */
  --fluid-glow: linear-gradient(110deg, #58a6ff, #a371f7, #f778ba);

  /* Typography */
  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--gh-bg);
  /* Subtle developer grid overlay */
  background-image: 
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 40px 40px;
  color: var(--gh-text);
  font-family: var(--font-ui);
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
}

/* Massive, pulsing ambient background glow */
body::before {
  content: "";
  position: absolute;
  top: -10%;
  left: 10%;
  width: 80%;
  height: 50vh;
  background: var(--fluid-glow);
  filter: blur(140px);
  opacity: 0.15;
  z-index: -1;
  animation: ambientPulse 12s ease-in-out infinite alternate;
}

@keyframes ambientPulse {
  0% { transform: scale(1) translate(0, 0); opacity: 0.1; }
  100% { transform: scale(1.05) translate(2%, 2%); opacity: 0.2; }
}

.compendium-header {
  text-align: center;
  margin-top: 80px;
  margin-bottom: 60px;
  max-width: 800px;
  padding: 0 20px;
  z-index: 1;
}

.repo-path {
  font-family: var(--font-mono);
  color: var(--gh-link);
  font-size: 0.95rem;
  margin-bottom: 20px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: rgba(56, 139, 253, 0.1);
  border: 1px solid rgba(56, 139, 253, 0.2);
  border-radius: 20px;
}

.compendium-header h1 {
  font-size: 3.5rem;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.1;
  margin: 0 0 16px 0;
  background: var(--fluid-glow);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.compendium-header p {
  color: var(--gh-muted);
  font-size: 1.15rem;
  margin: 0;
}

.mor-gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 24px;
  width: 100%;
  /* Removed the side padding so the cards sit flush with the left edge */
  padding: 0 0 80px 0; 
}

/* Layout Skeleton & Responsiveness */
.layout-container {
  display: flex;
  flex-wrap: wrap; /* Allows sidebar to drop elegantly on smaller screens */
  max-width: 1150px;
  width: 100%;
  margin: 0 auto;
  gap: 32px;
  padding: 0 20px;
  z-index: 1;
}

.layout-main {
  flex: 1;
  min-width: 300px; /* Prevents the grid from crushing inward */
}

.layout-sidebar {
  width: 320px;
  flex-shrink: 0;
}

/* Mobile trigger: Push sidebar below the grid on smaller screens */
@media (max-width: 850px) {
  .layout-sidebar {
    width: 100%;
  }
}

.mor-preset-card {
  background: var(--gh-panel);
  border-radius: 8px;
  border: 1px solid var(--gh-border);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  display: flex;
  flex-direction: column;
  position: relative;
}

/* Fluid Glass Border on Hover */
.mor-preset-card::after {
  content: "";
  position: absolute;
  top: -1px; left: -1px; right: -1px; bottom: -1px;
  border-radius: 8px;
  background: var(--fluid-glow);
  z-index: -1;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.mor-preset-card:hover {
  transform: translateY(-6px) scale(1.01);
  box-shadow: 0 16px 40px rgba(163, 113, 247, 0.15);
  border-color: transparent;
}

.mor-preset-card:hover::after {
  opacity: 1;
}

.card-gh-header {
  padding: 12px 16px;
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--gh-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--gh-border);
  border-radius: 8px 8px 0 0;
  background: var(--gh-panel);
}

.card-gh-footer {
  padding: 16px;
  background: var(--gh-panel);
  border-radius: 0 0 8px 8px;
  border-top: 1px solid var(--gh-border);
  display: flex;
  justify-content: flex-end;
}

.mor-copy-btn {
  background: #21262d;
  color: var(--gh-text);
  border: 1px solid rgba(240, 246, 252, 0.1);
  padding: 6px 14px;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  border-radius: 6px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: 0.2s cubic-bezier(0.3, 0, 0.5, 1);
  font-family: var(--font-ui);
}

.mor-copy-btn:hover {
  background: #30363d;
  border-color: #8b949e;
}

.mor-swatch {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  box-shadow: 0 2px 6px rgba(0,0,0,0.4);
  display: inline-block;
}

/* --------------------------------------
   Native Gadget Typography & Headers 
   -------------------------------------- */
.sidebar-section h2 {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--gh-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  border-bottom: 1px solid var(--gh-border);
  padding-bottom: 8px;
  margin-bottom: 16px;
  margin-top: 0;
}

.sidebar-section .widget {
  background: var(--gh-panel);
  border: 1px solid var(--gh-border);
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 24px;
}

/* Search Gadget Overrides */
#BlogSearch1 form {
  display: flex;
  gap: 8px;
}

#BlogSearch1 input.searchInput {
  flex: 1;
  background: var(--gh-bg);
  border: 1px solid var(--gh-border);
  color: var(--gh-text);
  padding: 8px 12px;
  border-radius: 6px;
  font-family: var(--font-ui);
  outline: none;
}

#BlogSearch1 input.searchInput:focus {
  border-color: var(--gh-link);
}

#BlogSearch1 input.searchButton {
  background: #21262d;
  color: var(--gh-text);
  border: 1px solid rgba(240, 246, 252, 0.1);
  padding: 8px 14px;
  border-radius: 6px;
  cursor: pointer;
  font-family: var(--font-ui);
  font-weight: 500;
  transition: 0.2s cubic-bezier(0.3, 0, 0.5, 1);
}

#BlogSearch1 input.searchButton:hover {
  background: #30363d;
  border-color: #8b949e;
}

/* Labels Gadget Overrides (Purple Ink Tag Badges) */
#Label1 ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

#Label1 ul li a {
  display: inline-block;
  background: rgba(163, 113, 247, 0.05);
  border: 1px solid rgba(163, 113, 247, 0.2);
  color: var(--gh-text);
  text-decoration: none;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-family: var(--font-mono);
  transition: all 0.3s ease;
}

#Label1 ul li a:hover {
  background: var(--fluid-glow);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(163, 113, 247, 0.25);
}

/* Archive Gadget Overrides */
#BlogArchive1 ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

#BlogArchive1 li {
  margin-bottom: 8px;
}

#BlogArchive1 a {
  color: var(--gh-link);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 13px;
}

#BlogArchive1 a:hover {
  text-decoration: underline;
}

/* Pagination Styling */
#blog-pager {
  display: flex;
  justify-content: space-between;
  width: 100%;
  max-width: 1150px;
  margin: 40px auto 0 auto;
  padding: 20px;
  border-top: 1px solid var(--gh-border);
}

#blog-pager a {
  color: var(--gh-link);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  padding: 8px 16px;
  border: 1px solid var(--gh-border);
  border-radius: 6px;
  background: var(--gh-panel);
  transition: all 0.2s ease;
}

#blog-pager a:hover {
  border-color: rgba(163, 113, 247, 0.5); /* Purple Ink Accent */
  background: rgba(163, 113, 247, 0.05);
  color: rgba(163, 113, 247, 1);
}

/* Ecosystem Footer */
.compendium-footer {
  width: 100%;
  border-top: 1px solid var(--gh-border);
  background: var(--gh-panel); /* Chalkboard gray base tone */
  padding: 60px 20px;
  margin-top: 100px;
  color: var(--gh-muted);
  font-family: var(--font-ui);
}

.footer-grid {
  max-width: 1150px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 40px;
}

.footer-col h4 {
  color: var(--gh-text);
  font-family: var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 0.85rem;
  margin-top: 0;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-col a {
  color: var(--gh-muted);
  text-decoration: none;
  transition: color 0.2s ease;
}

.footer-col a:hover {
  color: rgba(163, 113, 247, 1);
}

head.script:
//
class MorThemeGallery extends HTMLElement {
  connectedCallback() {
    setTimeout(() => this.hydrate(), 0);
  }

  async hydrate() {
    const rawPosts = Array.from(this.querySelectorAll('.preset-raw-data'));

    if (rawPosts.length === 0) {
      this.innerHTML = `<div style="text-align: center; padding: 4rem; color: var(--gh-muted); font-family: var(--font-mono);">[ No presets found in this workspace. ]</div>`;
      return;
    }

    this.innerHTML = `<div class="mor-gallery-grid"></div>`;
    const grid = this.querySelector('.mor-gallery-grid');

    for (const post of rawPosts) {
      const filename = post.querySelector('.preset-title').innerText.trim();
      const bodyHTML = post.querySelector('.preset-body').innerHTML;

      const urlMatch = bodyHTML.match(/https:\/\/cdn\.jsdelivr\.net[^"'\s<]+\.json/);

      if (urlMatch) {
        const cdnUrl = urlMatch[0];
        try {
          const rawRes = await fetch(cdnUrl);
          if (!rawRes.ok) throw new Error(`HTTP ${rawRes.status}`);
          const presetData = await rawRes.json();
          this.renderCard(grid, presetData, cdnUrl, filename);
        } catch (error) {
          this.renderErrorCard(grid, filename, `Fetch failed (${error.message}). Check if the JSON is pushed to your public GitHub repo.`);
        }
      } else {
         this.renderErrorCard(grid, filename, "No valid jsDelivr CDN link found in the Blogger post body.");
      }
    }
  }

  renderErrorCard(container, filename, errorMsg) {
     const card = document.createElement('div');
     card.className = 'mor-preset-card';
     card.style.border = "1px solid rgba(248, 81, 73, 0.5)"; // GitHub Error Red
     card.innerHTML = `
        <div class="card-gh-header" style="color: #f85149; border-bottom-color: rgba(248, 81, 73, 0.2);">
          ⚠️ ${filename}
        </div>
        <div style="background: var(--gh-panel); padding: 30px 24px; flex-grow: 1; border-radius: 0 0 8px 8px;">
          <h3 style="color: #f85149; margin-top: 0; font-family: var(--font-ui); font-size: 1.2rem;">Hydration Error</h3>
          <p style="color: var(--gh-text); font-family: var(--font-mono); font-size: 0.85rem;">${errorMsg}</p>
        </div>
     `;
     container.appendChild(card);
  }

  renderCard(container, data, downloadUrl, filename) {
    const base = data.base_config;
    const colors = data.dark.colors;
    const bgFill = typeof colors.bg_panel === 'string' ? colors.bg_panel : colors.bg_panel.color;

    const card = document.createElement('div');
    card.className = 'mor-preset-card';

    card.innerHTML = `
      <div class="card-gh-header">
        📄 ${filename}
      </div>
      <div style="background: ${bgFill}; padding: 30px 24px; display: flex; flex-direction: column; gap: 20px; flex-grow: 1;">
        <div>
          <h3 style="margin: 0; color: ${colors.accent}; font-family: '${base.typography.heading_font_stack}'; font-size: 1.6rem; line-height: 1.2;">${data.name}</h3>
          <p style="margin: 8px 0 0 0; font-size: 0.9rem; color: ${colors.fg_muted}; font-family: var(--font-ui); line-height: 1.5;">${data.description}</p>
        </div>
        <div style="display: flex; gap: 10px; margin-top: auto;">
          <span class="mor-swatch" style="background: ${colors.bg_base}; border: 1px solid ${colors.border};"></span>
          <span class="mor-swatch" style="background: ${colors.accent}; border: 1px solid ${colors.border};"></span>
          <span class="mor-swatch" style="background: ${colors.fg_base}; border: 1px solid ${colors.border};"></span>
        </div>
      </div>
      <div class="card-gh-footer">
        <button class="mor-copy-btn" data-url="${downloadUrl}">
          Copy JSON URL
        </button>
      </div>
    `;

    const btn = card.querySelector('.mor-copy-btn');
    btn.addEventListener('click', () => {
      navigator.clipboard.writeText(downloadUrl);
      const originalText = btn.innerText;
      btn.innerHTML = `✔ Copied!`;
      btn.style.borderColor = "#3fb950";
      btn.style.color = "#3fb950";
      setTimeout(() => {
        btn.innerHTML = originalText;
        btn.style.borderColor = "";
        btn.style.color = "";
      }, 2000);
    });

    container.appendChild(card);
  }
}

customElements.define('mor-theme-gallery', MorThemeGallery);
//
